// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.Executors;

import org.eclipse.rdf4j.sail.lmdb.config.FrontierEstimatorMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierMutation;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

class TripleStoreWriteRouteJournalCompositionTest {

	private static final long[] SUBJECTS = { 101L, 102L, 101L };
	private static final long[] PREDICATES = { 201L, 201L, 201L };
	private static final long[] OBJECTS = { 301L, 302L, 301L };
	private static final long[] CONTEXTS = { 0L, 99L, 0L };

	@ParameterizedTest
	@EnumSource(WriteRoute.class)
	void effectiveInsertionsRemainDurableAcrossPhysicalRoutes(WriteRoute route, @TempDir Path directory)
			throws Exception {
		LmdbStoreConfig config = config(FrontierEstimatorMode.AUTHORITATIVE);
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			store.startTransaction();
			write(store, route);
			store.commit();
			assertRows(store, 2);
			assertJournal(store);
		}
		try (TripleStore reopened = new TripleStore(directory.toFile(), config, null)) {
			assertRows(reopened, 2);
			assertJournal(reopened);
		}
	}

	@ParameterizedTest
	@EnumSource(WriteRoute.class)
	void abortedWritePublishesNeitherRowsNorJournal(WriteRoute route, @TempDir Path directory) throws Exception {
		try (TripleStore store = new TripleStore(directory.toFile(), config(FrontierEstimatorMode.AUTHORITATIVE),
				null)) {
			store.startTransaction();
			write(store, route);
			store.rollback();
			assertRows(store, 0);
			assertEquals(List.of(), store.readFrontierMutationsAfter(0L, 10));
			assertEquals(0L, store.frontierMutationJournalState().latestSequence());
		}
	}

	@ParameterizedTest
	@EnumSource(WriteRoute.class)
	void offModeRetainsOneDurableGapForEveryWriteRoute(WriteRoute route, @TempDir Path directory) throws Exception {
		try (TripleStore store = new TripleStore(directory.toFile(), config(FrontierEstimatorMode.OFF), null)) {
			store.startTransaction();
			write(store, route);
			store.commit();
			assertRows(store, 2);
			assertEquals(List.of(), store.readFrontierMutationsAfter(0L, 10));
			var state = store.frontierMutationJournalState();
			assertEquals(1L, state.latestSequence());
			assertEquals(1L, state.gapThroughSequence());
			assertEquals(0L, state.retainedMutationCount());
		}
	}

	private static void assertJournal(TripleStore store) throws IOException {
		List<FrontierMutation> mutations = store.readFrontierMutationsAfter(0L, 10);
		assertEquals(2, mutations.size(), "one durable journal row per effective insertion, never per duplicate input");
		assertEquals(List.of(1L, 2L), mutations.stream().map(FrontierMutation::sequence).toList());
		assertTrue(mutations.stream().allMatch(FrontierMutation::insertion));
		assertTrue(mutations.stream().allMatch(FrontierMutation::explicit));
		assertTrue(mutations.stream().allMatch(mutation -> mutation.epoch() > 0L));
		assertEquals(mutations.getFirst().epoch(), mutations.getLast().epoch());
		assertEquals(List.of(101L, 102L), mutations.stream().map(FrontierMutation::subjectId).sorted().toList());
		assertEquals(List.of(301L, 302L), mutations.stream().map(FrontierMutation::objectId).sorted().toList());
		assertEquals(List.of(0L, 99L), mutations.stream().map(FrontierMutation::contextId).sorted().toList());
		assertEquals(0L, store.frontierMutationJournalState().gapThroughSequence());
	}

	private static void assertRows(TripleStore store, int expected) throws IOException {
		try (var txn = store.getTxnManager().createReadTxn();
				var records = store.getTriples(txn, -1L, -1L, -1L, -1L, true)) {
			int count = 0;
			while (records.next() != null) {
				count++;
			}
			assertEquals(expected, count);
		}
	}

	private static void write(TripleStore store, WriteRoute route) throws Exception {
		switch (route) {
		case SCALAR -> {
			assertTrue(store.storeTriple(SUBJECTS[0], PREDICATES[0], OBJECTS[0], CONTEXTS[0], true));
			assertTrue(store.storeTriple(SUBJECTS[1], PREDICATES[1], OBJECTS[1], CONTEXTS[1], true));
			assertFalse(store.storeTriple(SUBJECTS[2], PREDICATES[2], OBJECTS[2], CONTEXTS[2], true));
		}
		case ALIGNED -> store.storeTriplesAligned(SUBJECTS, PREDICATES, OBJECTS, CONTEXTS, 3, true);
		case PREPARED -> {
			try (var executor = Executors.newFixedThreadPool(3)) {
				var prepared = store.prepareSecondaryIndexesAsync(executor, SUBJECTS, PREDICATES, OBJECTS, CONTEXTS, 3);
				try {
					store.storePreparedTriples(SUBJECTS, PREDICATES, OBJECTS, CONTEXTS, 3, true, false, null,
							prepared.awaitMain(), prepared::await);
				} finally {
					prepared.cancel();
				}
			}
		}
		case GLOBAL -> {
			assertTrue(store.supportsGlobalPreparedOrder(), "the fixture must execute the genuine global writer");
			assertTrue(store.isEmpty(), "global fresh import starts from a genuinely empty store");
			int[] quads = { 0, 2, 3, -1, 1, 2, 4, 5, 0, 2, 3, -1 };
			long[] values = { 101L, 102L, 201L, 301L, 302L, 99L };
			try (var executor = Executors.newFixedThreadPool(3)) {
				var prepared = store.prepareGlobalIndexOrdersAsync(executor, quads, values, 3);
				try {
					assertEquals(2, store.storeGloballyOrderedFreshTriples(quads, values, 3, prepared, executor));
				} finally {
					prepared.cancel();
				}
			}
		}
		}
	}

	private static LmdbStoreConfig config(FrontierEstimatorMode mode) {
		return new LmdbStoreConfig("spoc,ospc,posc,psoc").setFrontierEstimatorMode(mode);
	}

	enum WriteRoute {
		SCALAR,
		ALIGNED,
		PREPARED,
		GLOBAL
	}
}
